// Tests for the ds-bot Office CLI (src/office → office.js). Fixtures are the
// small packages under fixtures/office generated by dev/office-fixtures.py.
import { execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, test } from 'node:test'
import assert from 'node:assert'
import { readZip } from '../src/office/zip.js'
import { Package } from '../src/office/package.js'
import { checkPackage, fixPackage } from '../src/office/check.js'
import { docxRead } from '../src/office/docx.js'
import { pptxInventory, pptxLayout } from '../src/office/pptx.js'
import { xlsxInventory, xlsxRead } from '../src/office/xlsx.js'
import { decodePng, encodePng, contactSheet } from '../src/office/png.js'
import { parseXml } from '../src/office/xml.js'

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)))
const FIXTURES = join(ROOT, 'test', 'fixtures', 'office')
const CLI = join(ROOT, 'office.js')
const NODE = process.execPath

const fixture = (name) => join(FIXTURES, name)
const tmp = () => mkdtempSync(join(tmpdir(), 'office-test-'))

// exit 1 means "findings remain" — still a JSON result, not a failure.
const cli = (...args) => {
  try {
    return JSON.parse(execFileSync(NODE, [CLI, ...args, '--json'], { encoding: 'utf8' }))
  } catch (error) {
    if (error.stdout) return JSON.parse(error.stdout)
    throw error
  }
}

describe('zip', () => {
  test('round trip keeps unchanged members byte-identical', () => {
    const docx = fixture('sample.docx')
    const pkg = Package.open(docx)
    const before = readZip(readFileSync(docx))
    pkg.put('word/styles.xml', pkg.get('word/styles.xml')) // same bytes through put()
    const after = readZip(pkg.save())
    const a = before.find(m => m.name === 'word/document.xml')
    const b = after.find(m => m.name === 'word/document.xml')
    assert.deepEqual(b.raw, a.raw) // compressed bytes preserved for untouched parts
    assert.equal(after[0].name, '[Content_Types].xml')
    assert.equal(before.length, after.length)
  })

  test('rejects zip64 with a clear error', () => {
    const docx = readFileSync(fixture('sample.docx'))
    const copy = Buffer.from(docx)
    const eocd = copy.length - 22
    copy.writeUInt32LE(0xffffffff, eocd + 16)
    assert.throws(() => readZip(copy), /zip64/)
  })
})

describe('check', () => {
  const rules = [
    ['malformed-xml', (pkg) => pkg.put('word/styles.xml', '<w:styles><broken')],
    ['override-absent-part', (pkg) => pkg.overrides.set('word/ghost.xml', 'application/x')],
    ['dangling-rel', (pkg) => {
      const doc = pkg.xml('word/_rels/document.xml.rels')
      const rel = doc.createElement('Relationship')
      rel.setAttribute('Id', 'rId99'); rel.setAttribute('Type', 'x'); rel.setAttribute('Target', 'gone.xml')
      doc.documentElement.appendChild(rel)
      pkg.putXml('word/_rels/document.xml.rels', doc)
    }],
    ['missing-xml-space', (pkg) => {
      const doc = pkg.xml('word/document.xml')
      const p = parseXml('<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:r><w:t> tail</w:t></w:r></w:p>').documentElement
      doc.documentElement.appendChild(p.ownerDocument === doc ? p : doc.importNode(p, true))
      pkg.putXml('word/document.xml', doc)
    }],
  ]
  for (const [rule, breakIt] of rules) {
    test(`reports ${rule}`, () => {
      const pkg = Package.open(fixture('sample.docx'))
      breakIt(pkg)
      assert.ok(checkPackage(pkg).some(f => f.rule === rule), `no ${rule}`)
    })
  }
  test('clean fixture passes', () => {
    assert.deepEqual(checkPackage(Package.open(fixture('sample.docx'))), [])
    assert.deepEqual(checkPackage(Package.open(fixture('sample.pptx'))), [])
    assert.deepEqual(checkPackage(Package.open(fixture('sample.xlsx'))), [])
  })
  test('--against reports only new issues', () => {
    const original = Package.open(fixture('sample.docx'))
    const edited = Package.open(fixture('sample.docx'))
    const doc = edited.xml('word/_rels/document.xml.rels')
    const rel = doc.createElement('Relationship')
    rel.setAttribute('Id', 'rId99'); rel.setAttribute('Type', 'x'); rel.setAttribute('Target', 'gone.xml')
    doc.documentElement.appendChild(rel)
    edited.putXml('word/_rels/document.xml.rels', doc)
    const found = checkPackage(edited, original)
    assert.equal(found.length, 1)
    assert.equal(found[0].rule, 'dangling-rel')
  })
  test('--fix repairs missing-xml-space and dangling rels', () => {
    const pkg = Package.open(fixture('sample.docx'))
    const doc = pkg.xml('word/document.xml')
    const p = parseXml('<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:r><w:t> tail</w:t></w:r></w:p>').documentElement
    doc.documentElement.appendChild(doc.importNode(p, true))
    pkg.putXml('word/document.xml', doc)
    pkg.rels.get('word/document.xml').set('rId99', { id: 'rId99', type: 'x', target: 'gone.xml', mode: 'Internal' })
    const { remaining } = fixPackage(pkg)
    assert.deepEqual(remaining, [])
  })
})

describe('docx', () => {
  test('read gives pN/tN ids, tables, headers, comments', () => {
    const { blocks, sections, comments } = docxRead(Package.open(fixture('sample.docx')))
    assert.equal(blocks[0].id, 'p1')
    assert.equal(blocks[0].style, 'Title')
    const table = blocks.find(b => b.id === 't1')
    assert.equal(table.rows[0][0].gridSpan, 2)
    assert.ok(blocks.some(b => b.deletedParagraphMark))
    assert.equal(sections.find(s => s.kind === 'header').text, 'Report header')
    assert.equal(comments[0].author, 'Ana')
    assert.equal(comments[0].anchorsTo, 'p3')
  })
  test('read --changes marks tracked changes inline', () => {
    const { blocks } = docxRead(Package.open(fixture('sample.docx')), { changes: true })
    const text = blocks[1].text
    assert.match(text, /\{\+ fast \(Ana\)\+\}/)
    assert.match(text, /\{- old \(Ana\)-\}/)
  })
  test('replace works across runs and keeps start formatting', () => {
    const dir = tmp()
    const out = join(dir, 'out.docx')
    const res = cli('docx', 'edit', fixture('sample.docx'), '-o', out, '--ops',
      JSON.stringify([{ replace: { find: 'north region', with: 'south area' } }]))
    assert.ok(res.ok)
    const { blocks } = docxRead(Package.open(out))
    assert.match(blocks[1].text, /south area/)
    assert.deepEqual(cli('check', out, '--against', fixture('sample.docx')).data.findings, [])
  })
  test('all-or-nothing: a failing op writes nothing', () => {
    const dir = tmp()
    const out = join(dir, 'out.docx')
    assert.throws(() => execFileSync(NODE, [CLI, 'docx', 'edit', fixture('sample.docx'), '-o', out, '--ops',
      JSON.stringify([{ delete: { paragraphs: ['p1'] } }, { insert: { after: 'p999', text: 'x' } }]), '--json']))
    assert.ok(!existsSync(out))
  })
  test('accept and reject changes resolve to expected text', () => {
    const dir = tmp()
    const accepted = join(dir, 'a.docx'), rejected = join(dir, 'r.docx')
    cli('docx', 'edit', fixture('sample.docx'), '-o', accepted, '--ops', JSON.stringify([{ accept_changes: {} }]))
    cli('docx', 'edit', fixture('sample.docx'), '-o', rejected, '--ops', JSON.stringify([{ reject_changes: {} }]))
    const acc = docxRead(Package.open(accepted)).blocks[1].text
    const rej = docxRead(Package.open(rejected)).blocks[1].text
    assert.equal(acc, 'Revenue grew  fast in the north region. moved')
    assert.equal(rej, 'Revenue grew  in the north old region.')
  })
  test('set_cell, insert, delete, comment, set_field ops apply', () => {
    const dir = tmp()
    const out = join(dir, 'ops.docx')
    cli('docx', 'edit', fixture('sample.docx'), '-o', out, '--ops', JSON.stringify([
      { set_cell: { table: 1, row: 2, col: 2, text: '99' } },
      { insert: { after: 'p5', text: 'Added', style: 'Normal' } },
      { delete: { paragraphs: ['p4'] } },
      { comment: { paragraph: 'p2', text: 'Noted', author: 'Bo' } },
      { set_field: { match: 'PAGE', value: '7' } },
    ]))
    const { blocks, comments } = docxRead(Package.open(out))
    assert.equal(blocks.find(b => b.id === 't1').rows[1][1].text, '99')
    assert.ok(comments.some(c => c.author === 'Bo'))
    assert.deepEqual(cli('check', out, '--against', fixture('sample.docx')).data.findings, [])
  })
})

describe('pptx', () => {
  test('inventory resolves boxes incl. inherited placeholder and group transform', () => {
    const inv = pptxInventory(Package.open(fixture('sample.pptx')))
    assert.equal(inv.slideSize.cx, 10)
    const s1 = inv.slides[0]
    assert.equal(s1.layout, 'Title Slide')
    assert.equal(s1.notes, 'Speaker notes for the overview.')
    const title = s1.shapes.find(s => s.name === 'Title 1')
    assert.ok(title.box.w > 0) // box inherited from the layout placeholder
    assert.ok(s1.shapes.some(s => s.kind === 'chart') && s1.shapes.some(s => s.media))
    assert.equal(inv.slides[1].hidden, true)
  })
  test('layout reports overlap; autofit sets normAutofit', () => {
    const dir = tmp()
    const out = join(dir, 'fit.pptx')
    const res = cli('pptx', 'layout', fixture('sample.pptx'), '--autofit', '-o', out, '--json')
    assert.ok(res.data.findings.some(f => f.rule === 'overlap' && f.slide === 3))
    const fitted = pptxLayout(Package.open(out)).findings
    assert.ok(fitted.length > 0) // boxes unchanged; normAutofit flag written
  })
  test('slides reorder, duplicate, remove; check stays clean', () => {
    const dir = tmp()
    const out = join(dir, 'reordered.pptx')
    const res = cli('pptx', 'slides', fixture('sample.pptx'), '-o', out, '--order', '3,1,1')
    assert.deepEqual(res.data.order, [3, 1, 1])
    const inv = pptxInventory(Package.open(out))
    assert.equal(inv.slides.length, 3)
    assert.equal(inv.slides[0].part, 'ppt/slides/slide3.xml')
    assert.equal(checkPackage(Package.open(out)).length, 0)
  })
  test('clean --dry-run lists without removing', () => {
    const res = cli('pptx', 'clean', fixture('sample.pptx'), '--dry-run')
    assert.deepEqual(res.data.removed, [])
  })
})

describe('xlsx', () => {
  test('inventory lists sheets, names, formula counts', () => {
    const inv = xlsxInventory(Package.open(fixture('sample.xlsx')))
    assert.equal(inv.sheets[0].name, 'Sheet1')
    assert.equal(inv.sheets[0].formulas, 3)
    assert.equal(inv.sheets[0].merged, 1)
    assert.ok(inv.definedNames.some(n => n.name === 'Totals'))
  })
  test('read returns cached values, formulas and ISO dates', () => {
    const grid = xlsxRead(Package.open(fixture('sample.xlsx')), 'Sheet1')
    const row2 = grid.rows.find(r => r.row === 2).cells
    assert.equal(row2.D2.v, '2026-10-01')
    assert.equal(row2.C2.f, 'B2*2')
  })
})

describe('png + sheet', () => {
  test('decode/encode round trip', () => {
    const png = { width: 2, height: 2, data: Buffer.from([255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 0, 255]), channels: 4 }
    const decoded = decodePng(encodePng(png))
    assert.equal(decoded.width, 2)
    assert.deepEqual(decoded.data, png.data)
  })
  test('contact sheet dimensions and tiles', () => {
    const imgs = [1, 2, 3].map(() => ({ width: 10, height: 10, data: Buffer.alloc(400, 255) }))
    const sheet = contactSheet(imgs, { cols: 2, width: 10 })
    assert.equal(sheet.width, 20)
    assert.equal(sheet.height, 40)
  })
  test('sheet command writes a contact png', () => {
    const dir = tmp()
    const one = join(dir, '1.png'), two = join(dir, '2.png')
    writeFileSync(one, encodePng({ width: 4, height: 4, data: Buffer.alloc(64, 200), channels: 4 }))
    writeFileSync(two, encodePng({ width: 4, height: 4, data: Buffer.alloc(64, 100), channels: 4 }))
    const res = cli('sheet', dir, '-o', join(dir, 'out.png'), '--cols', '2', '--width', '4')
    const png = decodePng(readFileSync(res.data.file))
    assert.equal(png.width, 8)
  })
})

describe('unpack/pack', () => {
  test('unpack writes pretty XML and pack --against checks the result', () => {
    const dir = tmp()
    const dest = join(dir, 'un')
    cli('unpack', fixture('sample.docx'), dest)
    assert.ok(readFileSync(join(dest, 'word', 'document.xml'), 'utf8').includes('\n'))
    const res = cli('pack', dest, join(dir, 'back.docx'), '--against', fixture('sample.docx'))
    assert.ok(res.ok)
    assert.equal(checkPackage(Package.open(join(dir, 'back.docx'))).length, 0)
  })
})
